// Minimal RFC-4180 CSV parser — drop-in Papa.parse replacement for Fidelity CSVs.
// Handles: BOM, quoted fields, escaped quotes, header-mode, skipEmptyLines, transformHeader.
(function (global) {
  'use strict';

  function parse(text, cfg) {
    cfg = cfg || {};
    if (typeof text !== 'string') return { data: [], errors: [{ message: 'Input must be a string' }], meta: {} };

    // Strip UTF-8 BOM if present
    if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);

    // Normalise line endings
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    var delim = (typeof cfg.delimiter === 'string' && cfg.delimiter) ? cfg.delimiter : ',';
    var rows = [];
    var i = 0;
    var n = text.length;

    function parseRow() {
      var fields = [];
      while (i < n && text[i] !== '\n') {
        var field = '';
        if (text[i] === '"') {
          // Quoted field
          i++;
          while (i < n) {
            if (text[i] === '"') {
              if (text[i + 1] === '"') { field += '"'; i += 2; }  // escaped quote
              else { i++; break; }                                 // closing quote
            } else {
              field += text[i++];
            }
          }
        } else {
          // Unquoted field — read until delimiter or newline
          while (i < n && text[i] !== delim && text[i] !== '\n') field += text[i++];
        }
        fields.push(field);
        if (i < n && text[i] === delim) i++; // consume delimiter
      }
      if (i < n && text[i] === '\n') i++; // consume newline
      return fields;
    }

    while (i < n) {
      var row = parseRow();
      // skipEmptyLines
      if (cfg.skipEmptyLines && row.every(function (v) { return v.trim() === ''; })) continue;
      rows.push(row);
    }

    if (rows.length === 0) return { data: [], errors: [], meta: {} };

    if (cfg.header) {
      var headers = rows[0].map(function (h, idx) {
        return cfg.transformHeader ? cfg.transformHeader(h, idx) : h;
      });
      var data = [];
      for (var r = 1; r < rows.length; r++) {
        if (cfg.skipEmptyLines && rows[r].every(function (v) { return v.trim() === ''; })) continue;
        var obj = {};
        for (var c = 0; c < headers.length; c++) {
          obj[headers[c]] = rows[r][c] !== undefined ? rows[r][c] : '';
        }
        data.push(obj);
      }
      return { data: data, errors: [], meta: { fields: headers } };
    }

    return { data: rows, errors: [], meta: {} };
  }

  var Papa = { parse: parse };
  if (typeof module !== 'undefined' && module.exports) module.exports = Papa;
  else global.Papa = Papa;
}(this));
